-- =====================================================================
-- Sabores Royal — Dashboard de Pagos a Proveedores
-- =====================================================================
-- Mismo patron que el alquiler (supabase-migration-rent.sql): todo el
-- ledger vive en un unico registro de app_settings por clave, y solo
-- el panel de admin (autenticado) puede leerlo o escribirlo. La policy
-- de escritura para admins ya existe ("Admin write app settings" en
-- supabase-migration-2026.sql), asi que acá solo hace falta excluir
-- las claves nuevas de la lectura publica.
--
-- El seed es el historial importado de VENTAS GUILLE MODIF ok.xlsx
-- (hojas DEUDA PROVEEDOR, LA ESTRELLA y CHEQUES PROV), validado contra
-- los saldos que ya traía la planilla antes de cargarlo acá.
--
-- Seguro de correr más de una vez: el INSERT solo carga el historial
-- si la clave todavía no existe.
-- =====================================================================

DROP POLICY IF EXISTS "Public read app settings" ON app_settings;
CREATE POLICY "Public read app settings" ON app_settings
  FOR SELECT USING (setting_key NOT IN ('sub_admins', 'orders_list', 'rent_ledger', 'supplier_debts', 'supplier_checks'));

